// Test for whether advanced features are on
function usingAdvanced(a) {
  return (
    a.inspect_jdson_ld ||
    a.waitForDataLayer ||
    limiting_output(a) ||
    adding_to_page(a) ||
    other_analytics(a) ||
    a.inspect_json_ld ||
    a.waitForDataLayer
  );
}

// Test for whether an add functionality feature is on
function adding_to_page(a) {
  return (
    a.injectingGTM || a.injectingDataLayer || a.injectCode
  );
}

// Test for whether a control output feature is on
function limiting_output(a) {
  return (
    a.collapseBanner ||
    a.hideTiming ||
    a.showProperties ||
    a.hideStack ||
    a.show_cid ||
    a.hideHighlights ||
    a.showMessages ||
    a.showMutations ||
    a.highlightEvents ||
    a.ignoreEvents
  );
}

// Test for whether an other analytics feature is on
function other_analytics(a) {
  return (
    a.adobe ||
    a.tealium ||
    a.dtm ||
    a.ibm ||
    a.facebook ||
    a.mParticle ||
    a.doubleclick ||
    a.other ||
    a.gtmss ||
    a.segment
  );
}

function showAdvanced(vis) {
  let a = (settings = get_latest_settings());

  el("advanced-options-badge").innerHTML = usingAdvanced(a)
    ? "&nbsp;- ON"
    : "&nbsp;- OFF";
  el("insert-controls-badge").innerHTML = adding_to_page(a)
    ? "&nbsp;- ON"
    : "&nbsp;- OFF";
  el("hide-output-controls-badge").innerHTML = limiting_output(a)
    ? "&nbsp;- ON"
    : "&nbsp;- OFF";
  el("other-analytics-controls-badge").innerHTML = other_analytics(a)
    ? "&nbsp;- ON"
    : "&nbsp;- OFF";

  if (usingAdvanced(a)) {
    // Bold On
    el("advanced-options-badge").classList.add("badge_on");
  } else {
    el("advanced-options-badge").classList.remove("badge_on");
  }

  if (limiting_output(a)) {
    // Bold On
    el("hide-output-controls-badge").classList.add("badge_on");
  } else {
    el("hide-output-controls-badge").classList.remove("badge_on");
  }

  if (other_analytics(a)) {
    el("other-analytics-controls-badge").classList.add("badge_on");
  } else {
    el("other-analytics-controls-badge").classList.remove("badge_on");
  }

  if (adding_to_page(a)) {
    // Bold On
    el("insert-controls-badge").classList.add("badge_on");
  } else {
    el("insert-controls-badge").classList.remove("badge_on");
  }
  let img = "images/expand.png";
  if (vis && !firstOpen) {
    img = "images/collapse.png";
  }
  el("ap-advanced-toggle").src = img;
  toggle("advanced-options", a.inspectingDataLayer);
  toggle("advanced-options-contents", firstOpen ? false : vis);
  firstOpen = false
  toggle("dataLayer-push", vis);
  //toggle("classic-mode", vis)
  toggle("insert-controls", !a.classicMode && vis);
  toggle("hide-output-controls", !a.classicMode && vis);
  toggle("other-analytics-controls-container", !a.classicMode && vis);
  // toggle("show-messages", vis);
  // toggle("show-mutations", vis);
  // toggle("hide-timing", vis);
  // toggle("collapse-banner", vis);
  // toggle("hide-highlights", vis);
  // toggle("gtm-container-controls", vis)
  // toggle("code-push-controls", vis)
  // toggle("ignore-events-controls", vis)
  // toggle("show-property-controls", vis)
  // toggle("ignore-redirects", vis)
}

function toggle(e, b) {
  if (b) {
    el(e).classList.remove("invisible");
  } else {
    el(e).classList.add("invisible");
  }
}

