function clear_cd_names() {
  observered_ga_properties = {};
  const storage = { observered_ga_properties: observered_ga_properties };
  chrome.storage.local.set(storage);
}

function parse_cd_names(e) {
  const content = el("txt-cd-names").value.split("\n");
  const property = content[0].split("\t")[0];
  if (!/^UA-\d{1,10}-\d{1,3}$/.test(property)) {
    window.alert(`${property} is not a valid Google Analytics property ID.`);
  }
  const property_object = {
    id: property,
  };
  try {
    content.forEach((cd, i) => {
      if (i > 0) {
        const cd_array = cd.split("\t");
        property_object[`cd${cd_array[1]}`] = {
          name: cd_array[0],
          scope: cd_array[2],
          modified: cd_array[3],
          active: cd_array[4],
        };
      }
    });
    console.log(property_object);
    observered_ga_properties[property] = property_object;
    const storage = { observered_ga_properties };
    chrome.storage.local.set(storage);
  } catch (e) {
    alert(`The cd definitions are malformed\n${e.message}`);
  }
}
